import random
import math

# Simulate game dynamics to compare Day 1 canary strategies
# Employees: 40 total. Depts: Eng(4), Sales(4), Legal(9), Research(9), Finance(14)
DEPTS = {
    "Engineering": ["e00", "e24", "e25", "e33"],
    "Sales": ["e02", "e12", "e22", "e27"],
    "Legal": ["e03", "e11", "e14", "e16", "e19", "e30", "e32", "e34", "e35"],
    "Research": ["e04", "e05", "e06", "e13", "e15", "e18", "e20", "e28", "e39"],
    "Finance": ["e01", "e07", "e08", "e09", "e10", "e17", "e21", "e23", "e26", "e29", "e31", "e36", "e37", "e38"],
}
ALL_EMPS = [e for d in DEPTS.values() for e in d]
DEPT_NAMES = list(DEPTS.keys())

def choose_canary_assignment(probs, max_k=12):
    # Pick top suspects covering most probability mass, up to max_k, min 4 recipients
    ranked = sorted(ALL_EMPS, key=lambda e: probs[e], reverse=True)
    # Include suspects with significant probability
    active = [e for e in ranked if probs[e] > 0.005]
    if len(active) > max_k:
        # Take top max_k
        chosen = active[:max_k]
    elif len(active) >= 4:
        chosen = active
    else:
        # Pad with 0-prob innocents to reach 4 recipients, putting innocents on v3 if len(active)==2
        chosen = list(active)
        innocents = [e for e in ranked if probs[e] == 0]
        if not innocents:
            innocents = [e for e in reversed(ranked) if e not in chosen]
        while len(chosen) < 4:
            chosen.append(innocents.pop(0))
    # Partition chosen into 3 variants balanced by probability mass
    # Special case: if <=2 real suspects and padded with innocents, put suspect1->v1, suspect2->v2, innocents->v3
    real = [e for e in chosen if probs[e] > 0.005]
    if len(real) == 2 and len(chosen) >= 4:
        assign = {real[0]: "v1", real[1]: "v2"}
        for e in chosen:
            if e not in assign:
                assign[e] = "v3"
        return assign
    buckets = {"v1": [], "v2": [], "v3": []}
    b_mass = {"v1": 0.0, "v2": 0.0, "v3": 0.0}
    for e in chosen:
        b = min(b_mass, key=lambda k: (b_mass[k], len(buckets[k])))
        buckets[b].append(e)
        b_mass[b] += probs[e]
    # Ensure all 3 labels used if len(chosen) >= 3
    assign = {}
    for k, emps in buckets.items():
        for e in emps:
            assign[e] = k
    return assign

def choose_second_canary_orthogonal(probs, first_assign, max_k=12):
    chosen = list(first_assign.keys())
    real = [e for e in chosen if probs[e] > 0.005]
    if len(real) == 2 and len(chosen) >= 4:
        assign = {real[0]: "v1", real[1]: "v2"}
        for e in chosen:
            if e not in assign:
                assign[e] = "v3"
        return assign
    # Group by first_assign variant, distribute across v1, v2, v3
    by_v = {"v1": [], "v2": [], "v3": []}
    for e, v in first_assign.items():
        by_v[v].append(e)
    assign = {}
    idx = 0
    labels = ["v1", "v2", "v3"]
    for v in ["v1", "v2", "v3"]:
        for e in sorted(by_v[v], key=lambda x: probs[x], reverse=True):
            assign[e] = labels[idx % 3]
            idx += 1
    return assign

def pois(lam):
    L = math.exp(-lam)
    k = 0
    p = 1.0
    while p > L:
        k += 1
        p *= random.random()
    return k - 1

def run_ep(day1_mode):
    decoy = random.choice(ALL_EMPS)
    mole = random.choice([e for e in ALL_EMPS if e != decoy])
    true_V = 1.0
    docs = [] # (doc_id, day, set(recipients), is_canary, assign_dict)
    # Fixed Day 1 docs matching our actual game!
    docs.append(("d1-1", 1, set(DEPTS["Engineering"] + DEPTS["Sales"]), False, None))
    docs.append(("d1-2", 1, set(DEPTS["Engineering"] + DEPTS["Research"]), False, None))
    leaked_ids = set()
    scheduled_leaks = [] # (surface_day, doc_tuple, shown_variant)

    probs = {e: (0.0 if e == decoy else 1.0 / 39.0) for e in ALL_EMPS}

    for day in range(1, 22):
        if day > 1:
            n_new = random.choice([2, 3, 4])
            for j in range(n_new):
                d2 = random.sample(DEPT_NAMES, 2)
                recs = set(DEPTS[d2[0]] + DEPTS[d2[1]])
                docs.append((f"d{day}-{j+1}", day, recs, False, None))

        # Surface leaks today
        for s_day, doc, var in scheduled_leaks:
            if s_day == day:
                _, _, recs, is_c, assign = doc
                for e in ALL_EMPS:
                    if e not in recs:
                        probs[e] = 0.0
                    elif is_c:
                        n_v = len(set(assign.values()))
                        if n_v > 1:
                            probs[e] *= (0.95 if assign[e] == var else 0.05 / (n_v - 1))
                s = sum(probs.values())
                for e in ALL_EMPS:
                    probs[e] /= s

        # Check accusation threshold: P(top) > 0.985 or (day == 21 and P*V - (1-P) > 0)
        top_e = max(ALL_EMPS, key=lambda e: probs[e])
        top_p = probs[top_e]
        if top_p >= 0.985 or (day >= 18 and top_p >= 0.95) or (day == 21 and top_p * 0.5 - (1 - top_p) > 0):
            return true_V if top_e == mole else -1.0, day, top_e == mole

        # Decide canaries
        active_cnt = sum(1 for e in ALL_EMPS if probs[e] > 0.005)
        if day == 1:
            if day1_mode == "none":
                pass
            elif day1_mode == "one_13":
                # Research(9) + Sales(4)
                cands = DEPTS["Research"] + DEPTS["Sales"]
                assign = {}
                for i, e in enumerate(cands):
                    assign[e] = ["v1", "v2", "v3"][i % 3]
                docs.append(("c1-1", 1, set(assign.keys()), True, assign))
                true_V = max(0.0, true_V - 0.01)
            elif day1_mode == "two_split":
                # Canary 1: Research(9), Canary 2: Eng(4)+Sales(4)
                for idx_c, cands in enumerate([DEPTS["Research"], DEPTS["Engineering"] + DEPTS["Sales"]]):
                    assign = {e: ["v1", "v2", "v3"][i % 3] for i, e in enumerate(cands)}
                    docs.append((f"c1-{idx_c+1}", 1, set(assign.keys()), True, assign))
                    true_V = max(0.0, true_V - 0.01)
        elif day >= 3 and active_cnt <= 18:
            # Plant 1 or 2 targeted canaries if top_p < 0.985
            a1 = choose_canary_assignment(probs, max_k=14)
            docs.append((f"c{day}-1", day, set(a1.keys()), True, a1))
            true_V = max(0.0, true_V - 0.01)
            if active_cnt >= 3 and top_p < 0.92:
                a2 = choose_second_canary_orthogonal(probs, a1, max_k=14)
                docs.append((f"c{day}-2", day, set(a2.keys()), True, a2))
                true_V = max(0.0, true_V - 0.01)
        elif day >= 5 and active_cnt > 18:
            # If still broad by day 5, plant 2 canaries covering top 24 (12 + 12)
            ranked = [e for e in sorted(ALL_EMPS, key=lambda x: probs[x], reverse=True) if probs[e] > 0]
            for idx_c, chunk in enumerate([ranked[:12], ranked[12:24]]):
                if len(chunk) >= 4:
                    assign = {e: ["v1", "v2", "v3"][i % 3] for i, e in enumerate(chunk)}
                    docs.append((f"c{day}-{idx_c+1}", day, set(assign.keys()), True, assign))
                    true_V = max(0.0, true_V - 0.01)

        # End of day: logs + leak
        # Access logs update (for tomorrow)
        held_by = {e: any(e in d[2] for d in docs) for e in ALL_EMPS}
        for e in ALL_EMPS:
            if e == decoy:
                continue
            if held_by[e]:
                n_open = pois(1.0)
                p_ah = 0.3 if e == mole else 0.1
                ah = sum(1 for _ in range(n_open) if random.random() < p_ah)
                dt = n_open - ah
            else:
                ah, dt = 0, 0
            # Framing
            if e != mole and e != decoy:
                # Poisson(1/38) fake after hours
                ah += pois(1.0 / 38.0)
            # Update probs using exact Poisson likelihood (assuming held_by)
            if held_by[e]:
                # Mole: dt ~ Pois(0.7), ah ~ Pois(0.3)
                # Inn:  dt ~ Pois(0.9), ah ~ Pois(0.1 + 1/38)
                lam_ah_inn = 0.1 + 1.0 / 38.0
                lr = math.exp((0.9 + lam_ah_inn) - 1.0) * ((0.7 / 0.9) ** dt) * ((0.3 / lam_ah_inn) ** ah)
                probs[e] *= lr
        s = sum(probs.values())
        for e in ALL_EMPS:
            probs[e] /= s

        # Mole leak at end of day
        elig = [d for d in docs if (day - 2 <= d[1] <= day) and (mole in d[2]) and (d[0] not in leaked_ids)]
        if elig and random.random() < 0.65:
            weights = [(1.0 - len(d[2]) / 40.0) if d[3] else 1.0 for d in elig]
            tot_w = sum(weights)
            if tot_w > 0:
                r = random.random() * tot_w
                acc = 0.0
                picked = elig[-1]
                for d, w in zip(elig, weights):
                    acc += w
                    if r <= acc:
                        picked = d
                        break
                leaked_ids.add(picked[0])
                true_V = max(0.0, true_V - 0.05)
                delay = random.choice([2, 3])
                shown_v = None
                if picked[3]:
                    true_v = picked[4][mole]
                    all_v = list(set(picked[4].values()))
                    if len(all_v) == 1 or random.random() < 0.95:
                        shown_v = true_v
                    else:
                        shown_v = random.choice([v for v in all_v if v != true_v])
                scheduled_leaks.append((day + delay, picked, shown_v))

    return 0.0, 22, False

random.seed(42)
for mode in ["none", "one_13", "two_split"]:
    scores, days, wins = [], [], 0
    for _ in range(4000):
        sc, d, w = run_ep(mode)
        scores.append(sc)
        days.append(d)
        if w:
            wins += 1
    print(f"{mode:10s}: mean_score={sum(scores)/len(scores):.4f}, win_rate={wins/len(scores):.4f}, mean_day={sum(days)/len(days):.2f}")

